import 'package:flutter/painting.dart';

import '../models/coloring_category.dart';
import '../models/coloring_template.dart';

/// The ten categories and their fifty sketches.
///
/// Artwork for every entry is generated by tool/artwork/build.py into
/// `assets/coloring/<category>/<template>/`, and test/template_validation_test
/// checks that this catalogue and those assets agree.
class ColoringCatalog {
  ColoringCatalog._();

  static const List<ColoringCategory> categories = [
    ColoringCategory(
      id: 'flowers_garden',
      title: 'Flowers & Garden',
      color: Color(0xFFFFE3EC),
      coverTemplateId: 'flower',
      templateIds: ['flower', 'flower_pot', 'tree', 'mushroom', 'leaf'],
    ),
    ColoringCategory(
      id: 'pets_farm',
      title: 'Pets & Farm',
      color: Color(0xFFFFEBD6),
      coverTemplateId: 'cat',
      templateIds: ['cat', 'dog', 'cow', 'pig', 'chicken'],
    ),
    ColoringCategory(
      id: 'wild_animals',
      title: 'Wild Animals',
      color: Color(0xFFFFF4C9),
      coverTemplateId: 'lion',
      templateIds: ['elephant', 'turtle', 'lion', 'monkey', 'giraffe'],
    ),
    ColoringCategory(
      id: 'birds_insects',
      title: 'Birds & Insects',
      color: Color(0xFFE6F4D7),
      coverTemplateId: 'butterfly',
      templateIds: ['bird', 'duck', 'owl', 'butterfly', 'bee'],
    ),
    ColoringCategory(
      id: 'underwater_world',
      title: 'Underwater World',
      color: Color(0xFFD9F1FB),
      coverTemplateId: 'octopus',
      templateIds: ['fish', 'octopus', 'whale', 'crab', 'seahorse'],
    ),
    ColoringCategory(
      id: 'vehicles',
      title: 'Vehicles',
      color: Color(0xFFE3E8FF),
      coverTemplateId: 'car',
      templateIds: ['car', 'bus', 'train', 'airplane', 'boat'],
    ),
    ColoringCategory(
      id: 'buildings_places',
      title: 'Buildings & Places',
      color: Color(0xFFF1E4FA),
      coverTemplateId: 'house',
      templateIds: ['house', 'school', 'castle', 'shop', 'windmill'],
    ),
    ColoringCategory(
      id: 'fruits_vegetables',
      title: 'Fruits & Vegetables',
      color: Color(0xFFFFE5DC),
      coverTemplateId: 'strawberry',
      templateIds: ['apple', 'banana', 'strawberry', 'carrot', 'corn'],
    ),
    ColoringCategory(
      id: 'sky_weather',
      title: 'Sky & Weather',
      color: Color(0xFFDDF0FF),
      coverTemplateId: 'rainbow',
      templateIds: ['sun', 'cloud', 'rainbow', 'moon', 'snowman'],
    ),
    ColoringCategory(
      id: 'toys_imagination',
      title: 'Toys & Imagination',
      color: Color(0xFFDDF5EE),
      coverTemplateId: 'toy_robot',
      templateIds: ['teddy_bear', 'ball', 'kite', 'toy_robot', 'toy_rocket'],
    ),
  ];

  static const Map<String, String> _titles = {
    'flower': 'Flower',
    'flower_pot': 'Flower Pot',
    'tree': 'Tree',
    'mushroom': 'Mushroom',
    'leaf': 'Leaf',
    'cat': 'Cat',
    'dog': 'Dog',
    'cow': 'Cow',
    'pig': 'Pig',
    'chicken': 'Chicken',
    'elephant': 'Elephant',
    'turtle': 'Turtle',
    'lion': 'Lion',
    'monkey': 'Monkey',
    'giraffe': 'Giraffe',
    'bird': 'Bird',
    'duck': 'Duck',
    'owl': 'Owl',
    'butterfly': 'Butterfly',
    'bee': 'Bee',
    'fish': 'Fish',
    'octopus': 'Octopus',
    'whale': 'Whale',
    'crab': 'Crab',
    'seahorse': 'Seahorse',
    'car': 'Car',
    'bus': 'Bus',
    'train': 'Train',
    'airplane': 'Airplane',
    'boat': 'Boat',
    'house': 'House',
    'school': 'School',
    'castle': 'Castle',
    'shop': 'Shop',
    'windmill': 'Windmill',
    'apple': 'Apple',
    'banana': 'Banana',
    'strawberry': 'Strawberry',
    'carrot': 'Carrot',
    'corn': 'Corn',
    'sun': 'Sun',
    'cloud': 'Cloud',
    'rainbow': 'Rainbow',
    'moon': 'Moon',
    'snowman': 'Snowman',
    'teddy_bear': 'Teddy Bear',
    'ball': 'Ball',
    'kite': 'Kite',
    'toy_robot': 'Toy Robot',
    'toy_rocket': 'Toy Rocket',
  };

  static final Map<String, TemplateInfo> _templates = {
    for (final c in categories)
      for (final id in c.templateIds) id: TemplateInfo(id: id, title: _titles[id]!, categoryId: c.id),
  };

  static List<TemplateInfo> get allTemplates => _templates.values.toList(growable: false);

  static TemplateInfo? template(String id) => _templates[id];

  static ColoringCategory? category(String id) {
    for (final c in categories) {
      if (c.id == id) return c;
    }
    return null;
  }

  static List<TemplateInfo> templatesIn(String categoryId) =>
      category(categoryId)?.templateIds.map((id) => _templates[id]!).toList() ?? const [];
}
